@props(['collection' => null, 'resources'])
@php $initialResources = $collection ? $collection->resources->map(fn($resource) => ['id'=>$resource->id,'title'=>$resource->title])->values() : collect(); @endphp
<form method="POST" action="{{ $collection ? route('admin.resource-collections.update', $collection) : route('admin.resource-collections.store') }}" x-data="{ selected: @js($initialResources), choices: @js($resources), newId: '' }" x-init="$nextTick(() => $dispatch('admin-form-ready'))" class="mt-4 space-y-3">@csrf @if($collection) @method('PUT') @endif
    <label class="block text-sm font-semibold">Title<input name="title" required maxlength="160" value="{{ $collection?->title }}" class="mt-2 min-h-11 w-full rounded-xl border border-slate-300 p-3"></label>
    <label class="block text-sm font-semibold">Description<textarea name="description" maxlength="5000" class="mt-2 w-full rounded-xl border border-slate-300 p-3">{{ $collection?->description }}</textarea></label>
    <div class="flex flex-wrap gap-3"><select x-model="newId" aria-label="Resource to add" class="min-h-11 rounded-xl border border-slate-300 p-3"><option value="">Choose a resource</option>@foreach($resources as $resource)<option value="{{ $resource->id }}">{{ $resource->title }}</option>@endforeach</select><button type="button" @click="const resource = choices.find(item => String(item.id) === newId); if(resource &amp;&amp; !selected.some(item => item.id === resource.id)) selected.push(resource)" class="min-h-11 rounded-xl border border-slate-300 px-4">Add Resource</button></div>
    <ol class="space-y-2"><template x-for="(resource, index) in selected" :key="resource.id"><li class="flex flex-wrap items-center gap-3 rounded-xl bg-slate-50 p-3"><input type="hidden" name="resource_ids[]" data-track-unsaved="1" :value="resource.id"><span class="flex-1" x-text="resource.title"></span><button type="button" @click="if(index > 0) selected.splice(index-1, 0, selected.splice(index,1)[0])" class="min-h-11 px-2" aria-label="Move resource up">↑</button><button type="button" @click="if(index &lt; selected.length-1) selected.splice(index+1, 0, selected.splice(index,1)[0])" class="min-h-11 px-2" aria-label="Move resource down">↓</button><button type="button" @click="selected.splice(index,1)" class="min-h-11 px-2 text-rose-700">Remove</button></li></template></ol>
    <label class="flex min-h-11 items-center gap-2 text-sm"><input type="hidden" name="is_published" value="0"><input type="checkbox" name="is_published" value="1" @checked($collection?->is_published)>Published and available to assign</label><button class="min-h-11 rounded-xl bg-slate-900 px-4 py-2 text-white">Save Collection</button>
</form>
